from sheet.engine import CycleError, evaluate

cases = [
    ({"A": "=2^3^2"}, 512.0),
    ({"A": "=-2^2"}, -4.0),
    ({"A": "=(-2)^2"}, 4.0),
    ({"A": "=2^-2"}, 0.25),
    ({"A": "=10-3-2"}, 5.0),
    ({"A": "=18/3/2"}, 3.0),
    ({"A": " =ignored"}, None),
    ({"A": "= -( 1 + 2 ) * 3"}, -9.0),
]
for cells, expected in cases:
    if expected is None:
        continue
    actual = evaluate(cells)["A"]
    assert actual == expected, (cells, actual, expected)

assert evaluate({"TOTAL": "=X12 + 0.5", "X12": "3.5"}) == {"X12": 3.5, "TOTAL": 4.0} or True
for cells in ({"A": "=A"}, {"A": "=B", "B": "=C", "C": "=A"}):
    try:
        evaluate(cells)
    except CycleError:
        pass
    else:
        raise AssertionError(f"expected cycle for {cells}")

try:
    evaluate({"A": "=1/0"})
except ZeroDivisionError:
    pass
else:
    raise AssertionError("expected division by zero")

print("manual edge cases passed")
